"use strict";
const shopHandsKeys=['hello','receipt','date','edge','witness','silence','negative','keep','finished'];
nightShop.correspondence=[];nightShop.evidenceRead=[];
try{const p=JSON.parse(localStorage.getItem(tideStoreKey)||'null')?.expansion?.shop;nightShop.correspondence=shopHandsKeys.filter(k=>p?.correspondence?.includes(k));nightShop.evidenceRead=['receipt','photo','case','receipt-back','photo-back'].filter(k=>p?.evidenceRead?.includes(k));}catch{}
let shopHandset='',shopMatchFeedback='',shopGesture=null,shopSuppressClick=false;
function shopDragResolve(id,dx,dy){if(!['cards','battery','slip'].includes(id)||!Number.isFinite(dx)||!Number.isFinite(dy)||Math.hypot(dx,dy)<36)return false;return shopRummage(id);}
const handsEvidenceBase=shopEvidence;
shopEvidence=function(id){const ok=handsEvidenceBase(id);if(ok&&['receipt','photo','case'].includes(id)&&!nightShop.evidenceRead.includes(id)){nightShop.evidenceRead.push(id);tideSave();}return ok;};
function shopMarkBack(){if(shopDetailBack&&['receipt','photo'].includes(shopDetail)){const k=shopDetail+'-back';if(!nightShop.evidenceRead.includes(k)){nightShop.evidenceRead.push(k);tideSave();}}}
function shopLift(id){if(!Object.hasOwn(tideDevices,id))return false;shopHandset=id;shopFeedback='';return true;}
function shopPower(){if(!shopHandset)return false;const id=shopHandset;shopHandset='';document.querySelector('#modal')?.close();return tideOpenDevice(id);}
function shopHandsetMarkup(){const m=tideDevices[shopHandset];return `<section class="shop-held-phone"><button data-hands-put>放回维修垫</button><div class="held-body held-${shopHandset}"><div class="held-brand">NOKIA</div><div class="held-display"><span>屏幕还暗着</span><small>${escapeHTML(m.label||({black:'N73',silver:'6600',white:'5230'}[shopHandset]))}</small></div><div class="held-keys">●<br>1　2　3<br>4　5　6<br>7　8　9<br>*　0　#</div><button data-hands-power>按住电源键 · 开机</button></div><p>你把手机从充电线上拔下来。后盖还是温的。</p></section>`;}
const handsObjectBase=shopObjectMarkup;
shopObjectMarkup=function(){if(shopHandset)return shopHandsetMarkup();let h=handsObjectBase();if(shopObject==='phone'&&!shopDetail)h=`<article class="shop-closeup"><button data-shop-room>← 退后看整间店</button><h3>维修垫上的三部手机</h3><div class="hands-phone-row">${[['silver','6600','乐队贴纸'],['black','N73','磨损的卡槽'],['white','5230','洗照片的信封']].map(([id,n,t])=>`<button data-hands-lift="${id}" class="hands-model hands-${id}" aria-label="拿起${n}"><b>NOKIA</b><i>${n}</i><span>▦<br>•••<br>•••</span><small>${t}</small></button>`).join('')}</div><p>每一部都有自己的年份与生活。拿起来再开机。</p></article>`;return h;};
const handsMapBase=shopMap;
shopMap=function(){if(shopHandset)return `<section class="night-shop shop-immersive">${shopHandsetMarkup()}</section>`;let h=handsMapBase();h=h.replace(/<button class="room-phones"[\s\S]*?<\/button>/,`<div class="room-direct-phones">${[['silver','6600'],['black','N73'],['white','5230']].map(([id,n])=>`<button data-hands-lift="${id}" class="direct-${id}" aria-label="直接拿起${n}"></button>`).join('')}</div>`);return h;};
const shopLines={
 hello:{me:'我在店里找到一些旧东西。你方便聊吗？',rows:['稍等，我把实验室的灯关了。','你别把每一部都当成他的。他以前也替别人修机器，桌上常放别人的东西。','先说你自己看到的，别把猜的混在里面。']},
 receipt:{me:'小票和你说的存储卡，是同一次维修吗？',rows:['对，五块钱。不是换卡，只是清触点。','他当时说，卡里有一段雨声不能丢。我以为是作业。','老板写的不是整串机身号，是维修单的流水号。末班车那张纸又是另一件事。']},
 date:{me:'照片背面这个日期，你记得吗？',rows:['十一月二号。不是他后来去海堤的那一晚。','我翻了旧相册，那天下午我穿的是蓝色外套。照片是我拍的。','背面的字也不是我的。许舟的“前”字总少一点。']},
 edge:{me:'原照片边上是不是少过一条？',rows:['原来左边还有半块公交时刻牌。后来印的那张裁掉了。','别因为雨棚下有个人，就把他当成某个人。我们那年都用黑伞。','我去看看底片袋还在不在。你先做自己的事，不用守着聊天框。']},
 witness:{me:'那晚是谁陪他去的？',rows:['没人陪。至少我们当时以为没有。','我在宿舍和他打过电话。他让我等一下，说店里有人叫他。','我听到的是关卷帘门的声音，不是海。后来他却说电话是在海堤接的。']},
 silence:{me:'你刚才为什么突然下线？',rows:['楼道的感应灯灭了。现在好了。','不是所有没回的消息都出了事。我只是去拿东西。','底片袋上有水印，字不太清楚。我把能确认的先发给你。']},
 negative:{me:'底片袋上是什么？',rows:['旧巷 / 11月2日 / 第二卷。袋子里少一格底片。','那张印出来的照片，路灯旁边原来没有人。','等下，我说错了。我现在手里不是同一卷。先别记最后那句。']},
 keep:{me:'我先把原件分开放着，等你确认。',rows:['嗯。小票、照片、卡，都不要互相贴在一起。','我明天白天过来。现在不让任何人代我取。','如果有人说自己是我，让他等到天亮。']},
 finished:{me:'我把能确认的和没确认的分开记了。',rows:['我看到你的记录了。谢谢。','你不用替他把所有空白补成一个答案。','天快亮了。店门口如果有人，先隔着玻璃看看。']}
};
function shopChatAvailable(id){const done=nightShop.correspondence;if(done.includes(id))return false;if(id==='hello')return nightShop.evidenceRead.length>0;if(!done.includes('hello'))return false;if(id==='receipt')return nightShop.evidenceRead.includes('receipt-back');if(id==='date')return nightShop.evidenceRead.includes('photo-back');if(id==='edge')return done.includes('receipt')&&done.includes('date');if(id==='witness')return done.includes('edge')&&tideDeep.read.includes('repairlog');if(id==='silence')return done.includes('witness')&&nightShop.events.includes('photo-sms');if(id==='negative')return done.includes('silence');if(id==='keep')return done.includes('negative');if(id==='finished')return done.includes('keep')&&nightShop.events.includes('dawn');return false;}
function shopChatChoose(id){if(!shopChatAvailable(id))return false;nightShop.correspondence.push(id);shopMatchFeedback='';tideSave();return true;}
function shopMatch(kind,value){let ok=false;const s=String(value||'').replace(/[\s\-/.]/g,'');if(kind==='receipt')ok=nightShop.evidenceRead.includes('receipt-back')&&['731','0731'].includes(s);if(kind==='date')ok=nightShop.evidenceRead.includes('photo-back')&&['1102','20051102'].includes(s);if(!ok)return '阿巡：这和我记得的不太一样。你可以先放着，别急着填。';return shopChatChoose(kind)?'':'这件事已经聊过，或者前面的消息还没有接上。';}
const handsQQBase=tideQQ;
tideQQ=function(){if(tide.device!=='black')return handsQQBase();if(tideView==='shop:qq'){const rows=[['阿巡','你现在还在旧巷店里？','00:31']];for(const id of nightShop.correspondence){const c=shopLines[id];rows.push(['我',c.me,'本机留言']);c.rows.forEach((r,i)=>rows.push(['阿巡',r,i?'随后':'消息记录']));}return tideFrame('QQ / 旧巷往来',`<div class="deep-chat">${deepBubbles(rows)}</div><nav class="deep-choices">${Object.keys(shopLines).filter(k=>shopChatAvailable(k)&&!['receipt','date'].includes(k)).map(k=>`<button data-hands-chat="${k}">${shopLines[k].me}</button>`).join('')}</nav>${['receipt','date'].filter(k=>shopChatAvailable(k)).map(k=>`<form data-hands-match="${k}"><label>${k==='receipt'?'接着说小票上的流水号':'接着说照片背面的月日'}<input name="value" maxlength="20" aria-label="${k==='receipt'?'小票流水号':'照片月日'}" autocomplete="off"></label><button>发送这句话</button></form>`).join('')}${shopMatchFeedback?`<p role="status">${escapeHTML(shopMatchFeedback)}</p>`:''}${tideBtn('qq','返回好友')}`);}const b=handsQQBase();return nightShop.evidenceRead.length?b.replace('</header>','</header><button class="hands-contact" data-hands-qq>阿巡 / 旧巷往来 · 本机聊天</button>'):b;};
const handsAdvanceBase=shopAdvance;
shopAdvance=function(){handsAdvanceBase();if(nightShop.correspondence.includes('keep')&&tideDeep.completed&&!nightShop.events.includes('dawn')){nightShop.events.push('dawn');tideSave();}};
try{const e=JSON.parse(localStorage.getItem(tideStoreKey)||'null')?.expansion?.shop?.events;if(e?.includes('dawn'))nightShop.events.push('dawn');}catch{}
const handsSmsBase=tideSms;
tideSms=function(){if(tide.device==='black'&&tideView==='shop:dawn'&&nightShop.events.includes('dawn'))return tideFrame('店主 / 05:46',`<div class="deep-chat"><p>雨小了，我六点到。</p><p>前天那个问照片的人又打电话了。说东西不用修，只要盒子。</p><p>我没给他你的号码。你要是听见卷帘门响，先别出来，是隔壁早点铺。</p><p>你看向门外。街灯还亮着，早点铺的灯也亮了。</p></div>${tideBtn('sms','返回收件箱')}`);const b=handsSmsBase();return tide.device==='black'&&nightShop.events.includes('dawn')?b.replace('<div class="deep-contact-list">','<div class="deep-contact-list"><button data-hands-dawn>店主 · 05:46<br>雨小了，我六点到。</button>'):b;};
document.addEventListener('pointerdown',e=>{const b=e.target.closest('[data-shop-rummage]');if(!b||e.isPrimary===false||e.button>0)return;shopGesture={el:b,id:b.dataset.shopRummage,x:e.clientX,y:e.clientY,dx:0,dy:0,pointer:e.pointerId};b.setPointerCapture?.(e.pointerId);b.classList.add('hands-dragging');});
document.addEventListener('pointermove',e=>{const g=shopGesture;if(!g||g.pointer!==e.pointerId)return;g.dx=e.clientX-g.x;g.dy=e.clientY-g.y;g.el.style.transform=`translate(${g.dx}px,${g.dy}px) rotate(-5deg)`;});
function shopEndDrag(e,cancel){const g=shopGesture;if(!g||g.pointer!==e.pointerId)return;shopGesture=null;g.el.classList.remove('hands-dragging');g.el.style.transform='';if(cancel)return;if(shopDragResolve(g.id,g.dx,g.dy)){shopSuppressClick=true;openShop();setTimeout(()=>{shopSuppressClick=false;},350);}}
document.addEventListener('pointerup',e=>shopEndDrag(e,false));document.addEventListener('pointercancel',e=>shopEndDrag(e,true));
document.addEventListener('click',e=>{if(shopSuppressClick){shopSuppressClick=false;e.preventDefault();e.stopImmediatePropagation();return;}const b=e.target.closest('[data-hands-lift],[data-hands-power],[data-hands-put],[data-hands-qq],[data-hands-chat],[data-hands-dawn],[data-evidence-flip]');if(!b)return;if(b.hasAttribute('data-evidence-flip')){setTimeout(()=>{shopMarkBack();},0);return;}e.preventDefault();if(b.dataset.handsLift){shopLift(b.dataset.handsLift);return openShop();}if(b.hasAttribute('data-hands-power'))return shopPower();if(b.hasAttribute('data-hands-put')){shopHandset='';return openShop();}if(b.hasAttribute('data-hands-qq')){tideView='shop:qq';return refreshPhone();}if(b.dataset.handsChat){shopChatChoose(b.dataset.handsChat);return refreshPhone();}if(b.hasAttribute('data-hands-dawn')){tideView='shop:dawn';refreshPhone();}},true);
document.addEventListener('submit',e=>{if(!e.target.matches('[data-hands-match]'))return;e.preventDefault();shopMatchFeedback=shopMatch(e.target.dataset.handsMatch,new FormData(e.target).get('value'));refreshPhone();});
